pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        c.initialize();

        address priorOwner = c.owner();
        assertTrue(priorOwner == address(this));

        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);

        assertTrue(c.owner() == newOwner);
    }
}
